def generated_header() -> list[str]:
    return [
        "// <auto-generated>",
        "// Generated by vendor/tools/generate-vulkan-binding.py from vendor/native/vulkan/vk.xml.",
        "// Do not edit this file by hand; update the generator or pinned registry input instead.",
        "// </auto-generated>",
        "",
        "import System.C",
        "module Vendor.Vulkan",
        "",
    ]


def clean_int(value: str) -> str | None:
    value = value.strip()
    replacements = {
        "(~0U)": "4294967295",
        "(~1U)": "4294967294",
        "(~2U)": "4294967293",
        "(~0ULL)": "18446744073709551615",
    }
    if value in replacements:
        return replacements[value]
    if re.fullmatch(r"-?\d+", value):
        return value
    return None


def parse_numeric_enums(root: ET.Element) -> dict[str, str]:
    values: dict[str, str] = {}
    for enums in root.findall("enums"):
        group_name = enums.get("name") or ""
        if group_name not in {"API Constants", "VkResult", "VkStructureType"}:
            continue
        for enum in enums.findall("enum"):
            name = enum.get("name")
            raw_value = enum.get("value")
            if not name or raw_value is None:
                continue
            if (
                name not in SELECTED_CONSTANTS
                and name not in SELECTED_RESULTS
                and name not in SELECTED_STRUCTURES
            ):
                continue
            value = clean_int(raw_value)
            if value is not None:
                values[name] = value
    return values


def parse_header_version(root: ET.Element) -> int:
    for type_element in root.findall("./types/type"):
        if type_element.get("category") != "define":
            continue
        text = "".join(type_element.itertext())
        match = re.search(r"VK_HEADER_VERSION\s+(\d+)", text)
        if match:
            return int(match.group(1))
    raise RuntimeError("VK_HEADER_VERSION was not found in vk.xml")


def parse_handles(root: ET.Element) -> list[tuple[str, bool]]:
    handles: list[tuple[str, bool]] = []
    for type_element in root.findall("./types/type"):
        if type_element.get("category") != "handle":
            continue
        name_element = type_element.find("name")
        if name_element is None or not name_element.text:
            continue
        text = "".join(type_element.itertext())
        dispatchable = "VK_DEFINE_HANDLE" in text and "VK_DEFINE_NON_DISPATCHABLE_HANDLE" not in text
        handles.append((name_element.text, dispatchable))
    return sorted(handles, key=lambda item: item[0])


def emit_aliases(lines: list[str]) -> None:
    lines.extend(
        [
            "public alias VkResult = i32[min max];",
            "public alias VkStructureType = i32[min max];",
            "public alias VkBool32 = u32[0 max];",
            "public alias VkFlags = u32[0 max];",
            "public alias VkFlags64 = u64[0 max];",
            "public alias VkDeviceSize = u64[0 max];",
            "public alias VkDeviceAddress = u64[0 max];",
            "public alias VkSampleMask = u32[0 max];",
            "public alias VkInstanceCreateFlags = VkFlags;",
            "",
        ]
    )


def emit_constants(lines: list[str], values: dict[str, str], header_version: int) -> None:
    def const(name: str, value: str) -> None:
        lines.append(f"public const {name} = {value};")

    const("VK_HEADER_VERSION", str(header_version))
    const("VK_API_VERSION_1_0", str((1 << 22)))
    const("VK_API_VERSION_1_1", str((1 << 22) | (1 << 12)))
    const("VK_API_VERSION_1_2", str((1 << 22) | (2 << 12)))
    const("VK_API_VERSION_1_3", str((1 << 22) | (3 << 12)))
    const("VK_API_VERSION_1_4", str((1 << 22) | (4 << 12)))
    const("VK_HEADER_VERSION_COMPLETE", str((1 << 22) | (4 << 12) | header_version))
    for name in sorted(SELECTED_CONSTANTS | SELECTED_RESULTS | SELECTED_STRUCTURES):
        if name in values:
            const(name, values[name])
    lines.append("")


def emit_handles(lines: list[str], handles: list[tuple[str, bool]]) -> None:
    lines.append("// Generated Vulkan handle wrappers.")
    for name, dispatchable in handles:
        if dispatchable:
            drop_lines: list[str] = []
            if name == "VkInstance":
                drop_lines = [
                    "",
                    f"    public inline finite law bool IsEmpty(borrow {name} self)",
                    "    {",
                    "        return self.Handle == null;",
                    "    }",
                    "",
                    "    mut drop",
                    "    {",
                    "        unsafe",
                    "        {",
                    "            if (self.Handle != null)",
                    "            {",
                    "                vkDestroyInstance(self.Handle, null);",
                    "                self.Handle = null;",
                    "            }",
                    "        }",
                    "    }",
                ]

            lines.extend(
                [
                    f"internal struct {name}Native",
                    "{",
                    "    i8[min max] Opaque;",
                    "}",
                    "",
                    f"public struct {name}",
                    "{",
                    f"    internal rawmutptr<{name}Native> Handle;",
                    "",
                    f"    {name}()",
                    "    {",
                    "        self.Handle = null;",
                    "    }",
                    "",
                    f"    public inline finite law bool IsNull(borrow {name} self)",
                    "    {",
                    "        return self.Handle == null;",
                    "    }",
                    *drop_lines,
                    "}",
                    "",
                ]
            )
        else:
            lines.extend(
                [
                    f"public struct {name}",
                    "{",
                    "    internal u64[0 max] Handle;",
                    "",
                    f"    {name}()",
                    "    {",
                    "        self.Handle = 0;",
                    "    }",
                    "",
                    f"    public inline finite law bool IsNull(borrow {name} self)",
                    "    {",
                    "        return self.Handle == 0;",
                    "    }",
                    "}",
                    "",
                ]
            )


